def trf(language,key,**kwargs):
    text=tr(language,key)
    try:return text.format(**kwargs)
    except Exception:return text
def camera_label(language,camera):return tr(language,"camera_"+camera)
def assist_label(language,state):return tr(language,{0:"assist_manual",1:"assist_fsd",2:"assist_autosteer",3:"assist_tacc"}.get(state,"assist_manual"))
def event_reason_key(reason):
    raw=str(reason or "").strip().lower()
    if not raw:return "event_unknown"
    if "honk" in raw or "horn" in raw:return "event_honk"
    if "object" in raw or "aware" in raw or "camera_based" in raw:return "event_object"
    if "alarm" in raw or "glass" in raw:return "event_alarm"
    if "impact" in raw or "collision" in raw or "safety" in raw or "emergency" in raw:return "event_impact"
    if "save" in raw or "user_interaction" in raw or "manual" in raw or "dashcam" in raw:return "event_manual_save"
    if "sentry" in raw:return "event_sentry"
    return "event_unknown"
def event_reason_label(language,reason):
    key=event_reason_key(reason);label=tr(language,key)
    if key=="event_unknown" and reason:
        raw=str(reason).replace("_"," ").strip();return raw[:1].upper()+raw[1:] if raw else label
    return label
def translation_coverage():
    required=set(EN);coverage={}
    for lang in LANGUAGES:
        d=TRANSLATIONS.get(lang,{});matched=sum(1 for key in required if key in d and str(d[key]).strip());coverage[lang]=matched/max(1,len(required))
    return coverage
def translation_missing_keys():
    required=set(EN);return {lang:sorted(key for key in required if not str(TRANSLATIONS.get(lang,{}).get(key,"")).strip()) for lang in LANGUAGES}
